'use client'

import { useCallback, useMemo, useState, type MouseEvent, type ReactNode, type UIEvent } from 'react'
import { Check, ChevronDown, Loader2, X } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { cn } from '@/lib/utils'

import {
  defaultInfiniteSelectLabels,
  mergeById,
  useInfiniteSelectData,
  type InfiniteDataProps,
  type InfiniteSelectLabels,
  type SelectItemType,
} from './use-infinite-options'

export type { InfiniteQueryResult, InfiniteSource, QueryFn, SelectItemType } from './use-infinite-options'

type SelectSingleInfiniteScrollProps<T extends SelectItemType> = InfiniteDataProps<T> & {
  value?: string | null
  onChange: (value: string) => void
  onChangeItem?: (item: T | undefined) => void
  error?: boolean
  /**
   * What the field is called. The trigger's own text is the chosen value or a
   * placeholder, so without it a screen reader hears "Select…" with no idea
   * which field that is.
   */
  'aria-label'?: string
  'aria-describedby'?: string
  labels?: Partial<InfiniteSelectLabels>
  disabled?: boolean
  className?: string
  isEqualWidthPopoverContent?: boolean
  /** Max height of the list in px. */
  maxHeight?: number
  enabled?: boolean
  renderItem?: (item: T, isSelected: boolean) => ReactNode
  clearable?: boolean
  /**
   * Rendered under the list and inside the empty state — the way out when what
   * someone needs is not in the list yet, instead of a dead end.
   */
  footerAction?: ReactNode
  /** Message for a failed load, for a caller that knows its API's errors. Returning undefined keeps the default. */
  getErrorMessage?: (error: unknown) => string | undefined
  /** Contextual empty state, e.g. to tell an empty source from a search with no matches. */
  getEmptyMessage?: (search: string) => string
  /** Controls the open state from outside, e.g. to open the next picker after a choice. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

const SCROLL_THRESHOLD = 20

export function SelectSingleInfiniteScroll<T extends SelectItemType> ({
  queryFn,
  source,
  value,
  onChange,
  onChangeItem,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
  labels: labelsProp,
  disabled = false,
  className,
  maxHeight = 256,
  enabled = true,
  renderItem,
  error = false,
  isEqualWidthPopoverContent = true,
  clearable = false,
  footerAction,
  getErrorMessage,
  getEmptyMessage,
  open: controlledOpen,
  onOpenChange,
}: SelectSingleInfiniteScrollProps<T>) {
  const labels = useMemo(() => ({ ...defaultInfiniteSelectLabels, ...labelsProp }), [labelsProp])
  const [internalOpen, setInternalOpen] = useState(false)
  const isOpen = controlledOpen ?? internalOpen
  const setIsOpen = useCallback((next: boolean) => {
    setInternalOpen(next)
    onOpenChange?.(next)
  }, [onOpenChange])
  const [inputSearch, setInputSearch] = useState('')
  // Items the user picked, so the trigger keeps its label after the search that found them is gone.
  const [picked, setPicked] = useState<T[]>([])

  const selectedIds = useMemo(() => (value ? [value] : []), [value])

  const data = useInfiniteSelectData<T>({
    queryFn,
    source,
    inputSearch,
    // A preset value loads even while closed, otherwise the trigger shows the raw id.
    enabled: enabled && (isOpen || selectedIds.length > 0),
    selectedIds,
  })
  const { items, hasNextPage, isFetchingNextPage, fetchNextPage, isError, isFetching, isLoading } = data

  const selectedItem = useMemo(() => {
    if (!value) return undefined

    return [...items, ...data.selected, ...picked].find(item => item.id === value)
  }, [value, items, data.selected, picked])

  const handleRetry = data.retry

  // A failed load is not an empty list: saying "No results" sends people looking for a record that is there.
  const errorMessage = isError ? getErrorMessage?.(data.error) || labels.error : null
  const errorState = errorMessage
    ? (
      <div role='alert' className='space-y-2 py-3 text-center'>
        <p className='text-destructive text-xs'>{errorMessage}</p>
        <Button type='button' variant='outline' size='sm' disabled={isFetching} onClick={handleRetry}>
          {isFetching ? labels.loading : labels.retry}
        </Button>
      </div>
      )
    : null

  const emptyMessage = getEmptyMessage
    ? getEmptyMessage(data.search)
    : data.search ? labels.noResults : labels.empty

  const handleScroll = useCallback((e: UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget
    const isNearBottom = target.scrollTop + target.clientHeight >= target.scrollHeight - SCROLL_THRESHOLD

    if (isNearBottom && hasNextPage && !isFetchingNextPage) fetchNextPage()
  }, [hasNextPage, isFetchingNextPage, fetchNextPage])

  const handleSelect = useCallback((item: T) => {
    const nextItem = item.id === value ? undefined : item

    if (nextItem) setPicked(prev => mergeById(prev, [nextItem], true))
    onChange(nextItem?.id ?? '')
    onChangeItem?.(nextItem)
    setIsOpen(false)
  }, [onChange, onChangeItem, setIsOpen, value])

  const handleClear = useCallback((e: MouseEvent) => {
    e.stopPropagation()
    onChange('')
    onChangeItem?.(undefined)
  }, [onChange, onChangeItem])

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <Button
          type='button'
          variant='outline'
          role='combobox'
          aria-label={ariaLabel}
          aria-describedby={ariaDescribedBy}
          aria-invalid={error || undefined}
          aria-expanded={isOpen}
          className={cn(
            'w-full justify-between px-3 py-2 font-normal',
            error && 'border-destructive focus-visible:ring-destructive',
            className
          )}
          disabled={disabled}
        >
          <span className={cn('flex-1 truncate text-left', !selectedItem && 'text-muted-foreground')}>
            {selectedItem ? selectedItem.name : value || labels.placeholder}
          </span>
          <span className='ml-2 flex shrink-0 items-center gap-1'>
            {clearable && value && (
              <X
                aria-label={labels.clear}
                className='size-3.5 cursor-pointer text-muted-foreground hover:text-destructive'
                onClick={handleClear}
              />
            )}
            <ChevronDown className={cn('size-4 text-muted-foreground transition-transform', isOpen && 'rotate-180')} />
          </span>
        </Button>
      </PopoverTrigger>

      <PopoverContent
        align='start'
        className={cn(
          'p-0 gap-0',
          isEqualWidthPopoverContent
            ? 'w-(--radix-popover-trigger-width) max-w-[calc(100vw-1rem)]'
            : 'min-w-(--radix-popover-trigger-width) max-w-[calc(100vw-1rem)]'
        )}
      >
        <Command shouldFilter={false}>
          <CommandInput placeholder={labels.search} value={inputSearch} onValueChange={setInputSearch} />
          <CommandList
            onScroll={handleScroll}
            data-lenis-prevent
            className='scroll-fade no-scrollbar'
            style={{ maxHeight }}
          >
            <CommandEmpty>
              {isLoading
                ? (
                  <div className='flex items-center justify-center py-4 text-xs text-muted-foreground'>
                    <Loader2 className='mr-2 size-3.5 animate-spin' aria-hidden='true' />
                    {labels.loading}
                  </div>
                  )
                : (errorState ?? (
                  <div className='space-y-2 py-3 text-center'>
                    <p className='text-muted-foreground text-xs'>{emptyMessage}</p>
                    {footerAction}
                  </div>
                  ))}
            </CommandEmpty>

            <CommandGroup>
              {items.map(item => {
                const isSelected = item.id === value

                return (
                  <CommandItem
                    key={item.id}
                    value={item.id}
                    onSelect={() => handleSelect(item)}
                    className='my-0.5 cursor-pointer text-xs'
                  >
                    {renderItem
                      ? renderItem(item, isSelected)
                      : (
                        <div className='flex w-full items-center'>
                          <Check className={cn('mr-2 size-3.5', isSelected ? 'text-primary opacity-100' : 'opacity-0')} />
                          <span className='flex-1 truncate'>{item.name}</span>
                        </div>
                        )}
                  </CommandItem>
                )
              })}

              {isFetchingNextPage && (
                <div className='flex items-center justify-center py-2 text-xs text-muted-foreground'>
                  <Loader2 className='mr-2 size-3 animate-spin' aria-hidden='true' />
                  {labels.loadingMore}
                </div>
              )}

              {/* A later page that failed leaves the loaded ones in place. */}
              {items.length > 0 && errorState}

              {!hasNextPage && !isError && items.length > 0 && (
                <div className='border-t py-1.5 text-center text-xs text-muted-foreground/60'>
                  {labels.end}
                </div>
              )}
            </CommandGroup>

            {footerAction && items.length > 0 && <div className='border-t p-2'>{footerAction}</div>}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export default SelectSingleInfiniteScroll

'use client'

import { useCallback, useEffect, useMemo, useState, type ReactNode, type UIEvent } from 'react'
import { Check, ChevronDown, Loader2, X } from 'lucide-react'

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'

import {
  defaultInfiniteSelectLabels,
  mergeById,
  useInfiniteSelectData,
  type InfiniteDataProps,
  type InfiniteSelectLabels,
  type SelectItemType,
} from './use-infinite-options'

export type { InfiniteQueryResult, InfiniteSource, QueryFn, SelectItemType } from './use-infinite-options'

type RenderItemFn<T> = (item: T, isSelected: boolean, order?: number) => ReactNode
type RenderBadgeFn<T> = (item: T) => ReactNode

type SelectMultipleInfiniteScrollProps<T extends SelectItemType> = InfiniteDataProps<T> & {
  value: string[]
  onChange: (value: string[]) => void
  error?: boolean
  'aria-label'?: string
  'aria-describedby'?: string
  labels?: Partial<InfiniteSelectLabels>
  disabled?: boolean
  className?: string
  isEqualWidthPopoverContent?: boolean
  /** Max height of the list in px. */
  maxHeight?: number
  enabled?: boolean
  renderItem?: RenderItemFn<T>
  renderBadge?: RenderBadgeFn<T>
  showSelectAll?: boolean
  showClearAll?: boolean
  showSelectedCount?: boolean
  showSelectionOrder?: boolean
  /** Show the first choice plus "+N more" instead of one badge per choice. */
  collapseBadges?: boolean
}

const SCROLL_THRESHOLD = 20

function useItemSelection<T extends SelectItemType> (value: string[], onChange: (value: string[]) => void) {
  const selectedIds = useMemo(() => new Set(value), [value])

  const isSelected = useCallback((item: T) => selectedIds.has(item.id), [selectedIds])

  const getSelectionOrder = useCallback((item: T): number | undefined => {
    const index = value.indexOf(item.id)

    return index >= 0 ? index + 1 : undefined
  }, [value])

  const toggle = useCallback((item: T) => {
    onChange(selectedIds.has(item.id) ? value.filter(id => id !== item.id) : [...value, item.id])
  }, [value, onChange, selectedIds])

  const clearAll = useCallback(() => onChange([]), [onChange])

  const addItems = useCallback((items: T[]) => {
    const newIds = items.filter(item => !selectedIds.has(item.id)).map(item => item.id)

    if (newIds.length > 0) onChange([...value, ...newIds])
  }, [value, onChange, selectedIds])

  return { isSelected, getSelectionOrder, toggle, clearAll, addItems }
}

interface BadgeDisplayProps<T extends SelectItemType> {
  value: string[]
  itemsById: Map<string, T>
  collapseBadges: boolean
  labels: InfiniteSelectLabels
  renderBadge?: RenderBadgeFn<T>
  onClear: () => void
  onRemove: (id: string) => void
}

function BadgeDisplay<T extends SelectItemType> ({
  value,
  itemsById,
  collapseBadges,
  labels,
  renderBadge,
  onClear,
  onRemove,
}: BadgeDisplayProps<T>) {
  const renderLabel = (id: string) => {
    const item = itemsById.get(id)

    // Until the item resolves, the id is the only honest label.
    if (!item) return id

    return renderBadge ? renderBadge(item) : item.name
  }

  if (value.length === 0) {
    return <span className='text-muted-foreground'>{labels.placeholder}</span>
  }

  if (collapseBadges) {
    return (
      <Badge variant='secondary' className='flex max-w-full items-center gap-1 text-xs'>
        <span className='block truncate'>
          {renderLabel(value[0])}
          {value.length > 1 && (
            <span className='ml-1 font-semibold text-muted-foreground'>{labels.more(value.length - 1)}</span>
          )}
        </span>
        <X
          aria-label={labels.clearAll}
          className='size-3 shrink-0 cursor-pointer hover:text-destructive'
          onClick={(e) => {
            e.stopPropagation()
            onClear()
          }}
        />
      </Badge>
    )
  }

  return (
    <>
      {value.map(id => (
        <Badge key={id} variant='secondary' className='flex items-center gap-1 text-xs'>
          {renderLabel(id)}
          <X
            aria-label={labels.clear}
            className='size-3 cursor-pointer hover:text-destructive'
            onClick={(e) => {
              e.stopPropagation()
              onRemove(id)
            }}
          />
        </Badge>
      ))}
    </>
  )
}

interface SelectItemRowProps<T extends SelectItemType> {
  item: T
  isSelected: boolean
  order?: number
  showSelectionOrder: boolean
  renderItem?: RenderItemFn<T>
  onSelect: () => void
}

function SelectItemRow<T extends SelectItemType> ({
  item,
  isSelected,
  order,
  showSelectionOrder,
  renderItem,
  onSelect,
}: SelectItemRowProps<T>) {
  return (
    <CommandItem value={item.id} onSelect={onSelect} className='my-0.5 cursor-pointer text-xs'>
      {renderItem
        ? renderItem(item, isSelected, order)
        : (
          <div className='flex w-full items-center'>
            <Check className={cn('mr-2 size-3.5', isSelected ? 'text-primary opacity-100' : 'opacity-0')} />
            <span className='flex-1 truncate'>{item.name}</span>
            {showSelectionOrder && isSelected && order && (
              <Badge variant='default' className='ml-2 text-xs'>{order}</Badge>
            )}
          </div>
          )}
    </CommandItem>
  )
}

export function SelectMultipleInfiniteScroll<T extends SelectItemType> ({
  queryFn,
  source,
  value,
  onChange,
  labels: labelsProp,
  disabled = false,
  className,
  maxHeight = 256,
  enabled = true,
  renderItem,
  error = false,
  renderBadge,
  isEqualWidthPopoverContent = true,
  showSelectAll = true,
  showClearAll = true,
  showSelectedCount = true,
  showSelectionOrder = true,
  collapseBadges = true,
  'aria-label': ariaLabel,
  'aria-describedby': ariaDescribedBy,
}: SelectMultipleInfiniteScrollProps<T>) {
  const labels = useMemo(() => ({ ...defaultInfiniteSelectLabels, ...labelsProp }), [labelsProp])
  const [isOpen, setIsOpen] = useState(false)
  const [inputSearch, setInputSearch] = useState('')
  const [isAutoFetching, setIsAutoFetching] = useState(false)
  // Items the user picked, so badges keep their labels after the search that found them is gone.
  const [picked, setPicked] = useState<T[]>([])

  const { isSelected, getSelectionOrder, toggle, clearAll, addItems } = useItemSelection<T>(value, onChange)

  const data = useInfiniteSelectData<T>({
    queryFn,
    source,
    inputSearch,
    // Preset values load while closed so badges show names; a form reset to new ids does the same.
    enabled: enabled && (isOpen || value.length > 0),
    selectedIds: value,
  })
  const { items, hasNextPage, isFetchingNextPage, fetchNextPage, isFetching, isLoading, isError } = data

  const itemsById = useMemo(() => {
    const map = new Map<string, T>()

    for (const item of [...picked, ...items, ...data.selected]) map.set(item.id, item)

    return map
  }, [picked, items, data.selected])

  const allCurrentSelected = items.length > 0 && items.every(isSelected)
  const hasUnresolved = value.some(id => !itemsById.has(id))
  const isLoadingSelected = hasUnresolved && (isLoading || data.isFetchingSelected)

  const remember = useCallback((next: T[]) => setPicked(prev => mergeById(prev, next, true)), [])

  const handleSelectAll = useCallback(() => {
    addItems(items)
    remember(items)
    if (hasNextPage) setIsAutoFetching(true)
  }, [addItems, items, remember, hasNextPage])

  const handleClearAll = useCallback(() => {
    clearAll()
    setIsAutoFetching(false)
  }, [clearAll])

  const handleOpenChange = useCallback((next: boolean) => {
    setIsOpen(next)
    if (!next) {
      setInputSearch('')
      setIsAutoFetching(false)
    }
  }, [])

  const handleSearchChange = useCallback((next: string) => {
    setInputSearch(next)
    // "Select all" means all results of the search it was pressed on.
    setIsAutoFetching(false)
  }, [])

  const handleScroll = useCallback((e: UIEvent<HTMLDivElement>) => {
    if (isAutoFetching) return

    const target = e.currentTarget
    const isNearBottom = target.scrollTop + target.clientHeight >= target.scrollHeight - SCROLL_THRESHOLD

    if (isNearBottom && hasNextPage && !isFetchingNextPage) fetchNextPage()
  }, [hasNextPage, isFetchingNextPage, fetchNextPage, isAutoFetching])

  const handleRetry = data.retry

  const handleRemoveItem = useCallback((id: string) => {
    onChange(value.filter(v => v !== id))
  }, [value, onChange])

  // "Select all" walks every remaining page, adding each one as it lands.
  useEffect(() => {
    if (!isAutoFetching) return

    addItems(items)
    // Each page lands asynchronously, so there is no event to hang these on; keeps badge labels once the search moves on.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    remember(items)

    if (isError || !hasNextPage) {
      setIsAutoFetching(false)
    } else if (!isFetchingNextPage) {
      fetchNextPage()
    }
  }, [isAutoFetching, items, hasNextPage, isFetchingNextPage, isError, fetchNextPage, addItems, remember])

  return (
    <Popover open={isOpen} onOpenChange={handleOpenChange} modal>
      <PopoverTrigger asChild>
        <Button
          type='button'
          variant='outline'
          role='combobox'
          aria-label={ariaLabel}
          aria-describedby={ariaDescribedBy}
          aria-expanded={isOpen}
          aria-invalid={error || undefined}
          className={cn(
            'h-auto min-h-8 w-full justify-between px-3 py-1.5 font-normal',
            error && 'border-destructive focus-visible:ring-destructive',
            className
          )}
          disabled={disabled}
        >
          <span className='flex flex-1 flex-wrap gap-1 overflow-hidden'>
            {isLoadingSelected
              ? (
                <span className='flex flex-wrap gap-1'>
                  <Skeleton className='h-5 w-20' />
                  {value.length > 1 && <Skeleton className='h-5 w-16' />}
                </span>
                )
              : (
                <BadgeDisplay
                  value={value}
                  itemsById={itemsById}
                  collapseBadges={collapseBadges}
                  labels={labels}
                  renderBadge={renderBadge}
                  onClear={handleClearAll}
                  onRemove={handleRemoveItem}
                />
                )}
          </span>
          <ChevronDown className={cn('ml-2 size-4 shrink-0 text-muted-foreground transition-transform', isOpen && 'rotate-180')} />
        </Button>
      </PopoverTrigger>

      <PopoverContent
        align='start'
        className={cn(
          'p-0 gap-0',
          isEqualWidthPopoverContent
            ? 'w-(--radix-popover-trigger-width) min-w-72 max-w-[calc(100vw-1rem)]'
            : 'min-w-(--radix-popover-trigger-width) max-w-[calc(100vw-1rem)]'
        )}
      >
        <Command shouldFilter={false}>
          <div className='flex items-center border-b [&_[data-slot=command-input-wrapper]]:border-b-0'>
            <div className='min-w-0 flex-1'>
              <CommandInput placeholder={labels.search} value={inputSearch} onValueChange={handleSearchChange} />
            </div>

            {(showSelectAll || showClearAll) && (
              <div className='flex shrink-0 items-center gap-1 pr-1'>
                {showSelectAll && items.length > 0 && (
                  isAutoFetching
                    ? (
                      <div className='flex items-center gap-1'>
                        <Button type='button' variant='ghost' size='sm' onClick={() => setIsAutoFetching(false)}>
                          <X className='size-3' aria-hidden='true' />
                          {labels.cancel}
                        </Button>
                        <Loader2 className='size-4 animate-spin text-primary' aria-hidden='true' />
                      </div>
                      )
                    : (
                      <Button
                        type='button'
                        variant='ghost'
                        size='sm'
                        disabled={isFetching || (allCurrentSelected && !hasNextPage)}
                        onClick={handleSelectAll}
                      >
                        {labels.selectAll}
                      </Button>
                      )
                )}

                {showClearAll && value.length > 0 && (
                  <Button type='button' variant='ghost' size='sm' onClick={handleClearAll} disabled={isAutoFetching}>
                    {labels.clearAll}
                  </Button>
                )}
              </div>
            )}
          </div>

          <CommandList
            onScroll={handleScroll}
            data-lenis-prevent
            className='scroll-fade no-scrollbar'
            style={{ maxHeight }}
          >
            <CommandEmpty>
              {isLoading
                ? (
                  <div className='flex items-center justify-center py-4 text-xs text-muted-foreground'>
                    <Loader2 className='mr-2 size-3.5 animate-spin' aria-hidden='true' />
                    {labels.loading}
                  </div>
                  )
                : isError
                  ? (
                    <div role='alert' className='space-y-2 py-3 text-center'>
                      <p className='text-destructive text-xs'>{labels.error}</p>
                      <Button type='button' variant='outline' size='sm' disabled={isFetching} onClick={handleRetry}>
                        {isFetching ? labels.loading : labels.retry}
                      </Button>
                    </div>
                    )
                  : (
                    <p className='py-3 text-center text-xs text-muted-foreground'>
                      {data.search ? labels.noResults : labels.empty}
                    </p>
                    )}
            </CommandEmpty>

            <CommandGroup>
              {showSelectedCount && value.length > 0 && (
                <div className='mb-1 border-b bg-primary/10 px-2 py-1 text-xs text-primary'>
                  {labels.selectedCount(value.length)}
                </div>
              )}

              {items.map(item => (
                <SelectItemRow
                  key={item.id}
                  item={item}
                  isSelected={isSelected(item)}
                  order={getSelectionOrder(item)}
                  showSelectionOrder={showSelectionOrder}
                  renderItem={renderItem}
                  onSelect={() => {
                    if (!isSelected(item)) remember([item])
                    toggle(item)
                  }}
                />
              ))}

              {isFetchingNextPage && (
                <div className='flex items-center justify-center py-2 text-xs text-muted-foreground'>
                  <Loader2 className='mr-2 size-3 animate-spin' aria-hidden='true' />
                  {labels.loadingMore}
                </div>
              )}

              {items.length > 0 && isError && (
                <div role='alert' className='space-y-2 py-3 text-center'>
                  <p className='text-destructive text-xs'>{labels.error}</p>
                  <Button type='button' variant='outline' size='sm' disabled={isFetching} onClick={handleRetry}>
                    {isFetching ? labels.loading : labels.retry}
                  </Button>
                </div>
              )}

              {!hasNextPage && !isError && items.length > 0 && (
                <div className='border-t py-1.5 text-center text-xs text-muted-foreground/60'>
                  {labels.end}
                </div>
              )}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export default SelectMultipleInfiniteScroll

'use client'

import { useCallback, useEffect, useMemo, useReducer, useRef, useState } from 'react'

// ============================================
// Shared types
// ============================================

export interface SelectItemType {
  id: string
  name: string
}

export interface InfiniteQueryResult<T> {
  items: T[]
  nextCursor: string | null
  /** Items for the `selectedIds` the request asked for, so the trigger can show labels before they are paged in. */
  selected?: T[]
}

export type QueryFn<T> = (
  cursor: string | null,
  search: string,
  selectedIds?: string[],
  signal?: AbortSignal
) => Promise<InfiniteQueryResult<T>>

/**
 * Externally managed list state, e.g. mapped from TanStack `useInfiniteQuery`.
 * The select owns the search box and reports the debounced term through `onSearchChange`.
 */
export interface InfiniteSource<T> {
  items: T[]
  selected?: T[]
  hasNextPage: boolean
  fetchNextPage: () => unknown
  isLoading: boolean
  isFetchingNextPage: boolean
  isFetching?: boolean
  isError?: boolean
  error?: unknown
  retry?: () => unknown
  onSearchChange: (search: string) => void
}

/** `queryFn` and `source` are two ways to feed the same UI; pass exactly one. */
export type InfiniteDataProps<T> =
  | { queryFn: QueryFn<T>, source?: never }
  | { source: InfiniteSource<T>, queryFn?: never }

export interface InfiniteSelectLabels {
  placeholder: string
  search: string
  loading: string
  loadingMore: string
  end: string
  empty: string
  noResults: string
  error: string
  retry: string
  clear: string
  selectAll: string
  clearAll: string
  cancel: string
  selectedCount: (count: number) => string
  more: (count: number) => string
}

